#!/usr/bin/env python3
"""drive_index.py — one local index of everything Eric owns on Google Drive.

Lists Drive by the API (gws), never the mount, so it does not hang. Read-only:
it never moves, renames or deletes anything on Drive.

  python3 -I drive_index.py build              # list all owned files -> drive.sqlite (5-15 min)
  python3 -I drive_index.py find gps weekly    # every word must appear in the path or name
  python3 -I drive_index.py find gps --all     # also show _MACHINE, parked and unsorted copies
  python3 -I drive_index.py report             # duplicate, backup-folder and naming CSVs + summary
  python3 -I drive_index.py selftest

Output lives in ~/DEV/_INBOX/drive-index/ (gitignored: file names can be sensitive).
DexaProject is never stored (identifiable health data).
"""
import csv, json, re, sqlite3, subprocess, sys, time
from collections import defaultdict
from pathlib import Path

OUT = Path.home() / "DEV/_INBOX/drive-index"
DB = OUT / "drive.sqlite"
FOLDER = "application/vnd.google-apps.folder"
SHORTCUT = "application/vnd.google-apps.shortcut"
PRIMARY = "00_Primary_Storage_Drive"
EXCLUDE_NAMES = {"DexaProject"}                 # any folder by this name, at any depth
FIELDS = "nextPageToken,files(id,name,mimeType,size,md5Checksum,modifiedTime,parents)"

# Search order: the place a human should open first comes first.
ZONES = ["ladder", "reports", "archive", "personal", "pipeline", "primary_other",
         "root_other", "unsorted", "review", "parked", "computers", "machine", "unresolved"]
HIDDEN = {"unsorted", "review", "parked", "computers", "machine", "unresolved"}   # copies; `find --all` shows them
PIPELINE_ROOTS = ("Fireflies Meetings", "Zotero_PDFs",
                  f"{PRIMARY}/athlete-snapshots", f"{PRIMARY}/pff-snapshots")


def zone(path):
    """Where a file sits, from its folder path ('My Drive/...' prefix removed)."""
    if path is None:
        return "unresolved"
    if path.startswith("Computers/"):
        return "computers"
    if path.startswith("_MACHINE"):
        return "machine"
    if path == "_TO_REVIEW" or path.startswith("_TO_REVIEW/"):   # Grok bot's dedupe drop (10-22)
        return "review"
    if path.startswith(PIPELINE_ROOTS):
        return "pipeline"
    if not path.startswith(PRIMARY + "/"):
        return "root_other"
    top = path[len(PRIMARY) + 1:].split("/", 1)[0]
    if top == "10_ARCHIVE":
        return "parked" if path.startswith(f"{PRIMARY}/10_ARCHIVE/_PARKED_COPIES") else "archive"
    if top == "03_REPORTS":
        return "reports"
    if top == "99_UNSORTED":
        return "unsorted"
    if top == "11_PERSONAL":
        return "personal"
    if re.match(r"0\d_", top):
        return "ladder"
    return "primary_other"


def resolve(parent_of, name_of, root_id, fid):
    """Folder path of item `fid` ('' = My Drive root), or None if it never reaches a root.

    A parentless folder that is not My Drive is a Backup-and-Sync computer ("My Laptop (2)"):
    its tree is returned as "Computers/<name>/...".
    """
    parts, seen, cur, last = [], set(), parent_of.get(fid), None
    while cur and cur != root_id:
        if cur in seen or cur not in name_of:      # cycle, or a parent Eric does not own
            return None
        seen.add(cur)
        parts.append(name_of[cur])
        last, cur = cur, parent_of.get(cur)
    if cur == root_id:
        return "/".join(reversed(parts))
    if cur is None and last is not None:
        return "Computers/" + "/".join(reversed(parts))
    return None


def gws(params):
    """One files.list page. stdout only: gws prints its keyring line to stderr."""
    for attempt in range(1, 6):
        r = subprocess.run(["gws", "drive", "files", "list", "--params", json.dumps(params)],
                           capture_output=True, text=True)
        try:
            data = json.loads(r.stdout)
            if "files" in data:
                return data
        except json.JSONDecodeError:
            pass
        print(f"  page failed (try {attempt}): {r.stderr.strip()[-200:]}", flush=True)
        time.sleep(5 * attempt)
    sys.exit("gws list failed 5 times; nothing written")


def root_id():
    r = subprocess.run(["gws", "drive", "files", "get", "--params",
                        json.dumps({"fileId": "root", "fields": "id"})], capture_output=True, text=True)
    return json.loads(r.stdout)["id"]


def missing_ancestors(parent_of, name_of, root_id):
    """First ancestor id, per chain, that the listing never returned."""
    missing = set()
    for fid in parent_of:
        cur, seen = parent_of[fid], set()
        while cur and cur != root_id and cur in name_of and cur not in seen:
            seen.add(cur)
            cur = parent_of.get(cur)
        if cur and cur != root_id and cur not in name_of:
            missing.add(cur)
    return missing


def repair(parent_of, name_of, root_id, cap=3000):
    """Fetch folders the paged listing skipped, so their whole subtree gets a path."""
    fetched, tried = 0, set()
    while True:
        todo = missing_ancestors(parent_of, name_of, root_id) - tried
        if not todo or fetched >= cap:
            break
        for fid in list(todo)[:cap - fetched]:
            tried.add(fid)
            r = subprocess.run(["gws", "drive", "files", "get", "--params", json.dumps(
                {"fileId": fid, "fields": "id,name,mimeType,parents,trashed"})], capture_output=True, text=True)
            try:
                d = json.loads(r.stdout)
            except json.JSONDecodeError:
                continue                            # no access (someone else's folder): stays unresolved
            if d.get("mimeType") == FOLDER and not d.get("trashed"):
                name_of[fid] = d["name"]
                parent_of[fid] = (d.get("parents") or [None])[0]
                fetched += 1
    print(f"repair: fetched {fetched} skipped ancestor folders ({len(tried)} tried)", flush=True)

